        col = //texture(iChannel0, uv).xyz * // Get the vides pixel
        palette(iTime/5.0, vec3(.5,1.,.75), vec3(0.5,0.5,1.5), vec3(-1.0,1.0,2.0), vec3(0.0, 0.1, 0.2)); // Multiply by the color overlay
